{"command": "python3 -c "
import sys, time
sys.path.insert(0, '/opt/keygen')
import bridge

# Test setting 64 rows * 8 channels = 512 cells
# Let's test single calls vs batch via JSON
calls = []
for r in range(64):
    for c in range(8):
        calls.append({
            'name': 'pattern_set_cell',
            'arguments': {
                'pattern': 0,
                'row': r,
                'channel': c,
                'note': 'C-4',
                'instrument': 1,
                'volume': 64
            }
        })

t0 = time.time()
# Test sending calls in batches or through a script
# bridge.exchange takes one message: {'op': 'call', ...}
# Let's see how long 512 exchanges take
for item in calls[:50]:
    bridge.exchange({'op': 'call', 'name': item['name'], 'arguments': item['arguments']})
t1 = time.time()
print(f'50 calls took {t1 - t0:.3f} s ({(t1 - t0)/50*1000:.2f} ms per call)')
""}

